use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock once, at the start of the run.
        let seconds = wall_clock::now().seconds;

        // Exactly one permitted fetch. A transport failure comes back as a
        // value (Err), so it is recorded as zero characters rather than
        // trapping. An out-of-allowlist host still traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notify only with the guest's own numbers; the feed body is never
        // forwarded, so untrusted text does not reach the notifier.
        let message = format!("heartbeat t={} fetched={}", seconds, fetched);
        let notified = notifier::notify(&message);

        // The contract is `ensures notified == true`. If the channel refused
        // the notification, no output can satisfy it, so trap instead of
        // returning a report that violates the ensures.
        if !notified {
            panic!("notifier refused the heartbeat; ensures notified == true cannot hold");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
